// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.automation.diimport com.roshan.persona.automation.engine.AutomationEngineimport com.roshan.persona.automation.scheduler.AutomationSchedulerimport com.roshan.persona.automation.skills.CreateAutomationSkillimport com.roshan.persona.automation.skills.DisableAutomationSkillimport com.roshan.persona.automation.skills.EnableAutomationSkillimport com.roshan.persona.automation.skills.ListAutomationsSkillimport com.roshan.persona.brain.skill.BrainSkillimport dagger.Bindsimport dagger.Moduleimport dagger.hilt.InstallInimport dagger.hilt.components.SingletonComponentimport dagger.multibindings.IntoSetimport javax.inject.Singleton/** * NOUS — Automation Hilt Module (Module 8). * * Binds: *   - 4 automation skills (Create/List/Enable/Disable) via `@Binds @IntoSet` *     multibinding. Brain's [com.roshan.persona.brain.skill.registry.SkillRegistry] *     auto-discovers them at app startup. * * Provides: *   - [AutomationEngine] (Singleton) — the rule store + action executor. *   - [AutomationScheduler] (Singleton) — the WorkManager + Geofence + receiver *     orchestrator. * * ## Skill Registration * * Each `@Binds @IntoSet` adds one skill to Brain's `Set<BrainSkill>` multibinding. * The SkillRegistry receives the set via Hilt constructor injection and makes * them available to [com.roshan.persona.brain.skill.router.SkillRouter]. * * ## Wiring summary * * ``` * :app (Application) *   └── Hilt component graph *        ├── AutomationEngine (@Singleton) *        │     ├── AutomationScheduler (@Singleton) *        │     ├── SystemOperationExecutor (@Singleton, from :feature:system) *        │     └── BrainBus (@Singleton, from :feature:brain) *        ├── AutomationScheduler (@Singleton) *        │     └── @ApplicationContext Context *        ├── CreateAutomationSkill (@Singleton, @IntoSet) *        ├── ListAutomationsSkill  (@Singleton, @IntoSet) *        ├── EnableAutomationSkill (@Singleton, @IntoSet) *        └── DisableAutomationSkill(@Singleton, @IntoSet) * ``` * * @see <a href="docs/strategy/NOUS-Strategy-2-14-extracted.txt">§2.2 Automation</a> */@Module@InstallIn(SingletonComponent::class)abstract class AutomationModule {    // ─── Skill multibinding ─────────────────────────────────────────────────    @Binds @IntoSet    @Singleton    abstract fun bindCreateAutomationSkill(impl: CreateAutomationSkill): BrainSkill    @Binds @IntoSet    @Singleton    abstract fun bindListAutomationsSkill(impl: ListAutomationsSkill): BrainSkill    @Binds @IntoSet    @Singleton    abstract fun bindEnableAutomationSkill(impl: EnableAutomationSkill): BrainSkill    @Binds @IntoSet    @Singleton    abstract fun bindDisableAutomationSkill(impl: DisableAutomationSkill): BrainSkill}/** * Wiring note for [AutomationEngine] + [AutomationScheduler]. * * Both classes use `@Singleton @Inject constructor(...)` — Hilt auto-provides * them without needing explicit `@Provides` here. (Hilt does not allow both * `@Inject constructor` AND `@Provides` for the same type — duplicate binding.) * * The wiring is: * * ``` * AutomationEngine (@Singleton @Inject) *   ├── @ApplicationContext Context *   ├── AutomationScheduler (@Singleton @Inject) *   │     └── @ApplicationContext Context *   ├── SystemOperationExecutor (@Singleton, from :feature:system's SystemModule) *   └── BrainBus (@Singleton @Inject, from :feature:brain) * ``` * * If a future revision needs to swap implementations (e.g., add Room-backed * persistence), remove the `@Inject constructor` from the impl class and add * a `@Provides` method here returning the interface. */